Lemma deand_sound : forall E e e' s,
  deand e = (e', s) ->
  (0 <= s)%Z /\ exists rho, (0 <= rho <= s)%Z /\ eqm (bv_unsigned (edenot E e)) (bv_unsigned (edenot E e') - rho)%Z.
