Lemma round_itv_sound : forall g lo hi v,
  (0 <= g)%Z -> (2 ^ g | v)%Z -> (lo <= v <= hi)%Z ->
  (fst (round_itv g lo hi) <= v <= snd (round_itv g lo hi))%Z.
