#[using="Type"] Lemma word_byte_at : forall w d (V : word), (Z.to_nat d + 1 <= w)%nat -> (0 <= d)%Z ->
  firstn 1 (skipn (Z.to_nat d) (word_to_le_bytes w V))
  = [Z_to_bv 8 ((bv_unsigned V / 2 ^ (8 * d)) mod 256)%Z].
