#[using="Type"] Theorem sym_execT_ex : forall t fuel first stops ss E base rom ms,
  itab_sound segs t ->
  st_ok segs E base rom ss ms ->
  let ss' := sym_execT segs t fuel first stops ss in
  exists R, regs_ok E (s_regs ss') R
