Fixpoint kn_words_le8 (kn : list kentry) : Prop :=
  match kn with
  | [] => True
  | KWord _ w' _ :: r => (w' <= 8)%nat /\ kn_words_le8 r
  | _ :: r => kn_words_le8 r
  end.

#[using="Type"] Lemma know_ok_words_le8 : forall E M kn, know_ok segs E M kn -> kn_words_le8 kn.
Proof.
