(* [comment removed for export] *)
#[using="Type"] Lemma know_ok_unk_intro : forall E M (a : saddr) (bs : list byte) (ne : expr),
  flat E a (Z.of_nat (length bs)) -> elenZ E ne = Z.of_nat (length bs) ->
